CREATE TABLE basic_robot (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    icon_url VARCHAR(1000) NOT NULL,
    title_zh VARCHAR(255),
    title_en VARCHAR(255),
    robot_type VARCHAR(32) NOT NULL DEFAULT 'OTHER',
    action_mapping_support VARCHAR(16) NOT NULL DEFAULT 'UNSUPPORTED',
    description TEXT,
    company VARCHAR(100),
    introduction_url VARCHAR(1000),
    built_in BOOLEAN NOT NULL DEFAULT FALSE,
    deleted BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_basic_robot_name UNIQUE (name),
    CONSTRAINT ck_basic_robot_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT ck_basic_robot_icon_not_blank CHECK (btrim(icon_url) <> ''),
    CONSTRAINT ck_basic_robot_type CHECK (
        robot_type IN (
            'HUMANOID', 'MOBILE_MANIPULATOR', 'DESKTOP_ARM', 'MOBILE_BASE',
            'QUADRUPED', 'INDUSTRIAL_ARM', 'OTHER'
        )
    ),
    CONSTRAINT ck_basic_robot_action_mapping CHECK (
        action_mapping_support IN ('SUPPORTED', 'COMING_SOON', 'UNSUPPORTED')
    ),
    CONSTRAINT ck_basic_robot_deleted CHECK (deleted_at IS NULL OR deleted = TRUE)
);

CREATE INDEX idx_basic_robot_catalog
    ON basic_robot (deleted, robot_type, name);

