INSERT INTO sys_role_permission (role_id, permission_id)
SELECT r.id, p.id
FROM sys_role r
CROSS JOIN sys_menu_permission p
WHERE r.code IN ('SUPER_ADMIN', 'MANAGER')
  AND p.code IN ('basic:view', 'basic:robot:view')
ON CONFLICT DO NOTHING;
